// ===============================================================
// SHADER DEFINITIONS
// ===============================================================

// 1. Shaders for the 2D Background

// The Vertex Shader for the background. Its main job is to position the vertices
// of the rectangle that will cover the screen.
const vertShader2D = `#ifdef GL_ES
precision highp float;
#endif
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main() {
  vTexCoord = aTexCoord; // Pass the texture coordinate to the fragment shader.
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  // This is a key trick: by setting the z-component to 1.0, we force this
  // background rectangle to be at the furthest possible depth, ensuring
  // any 3D objects will be drawn in front of it.
  gl_Position = vec4(positionVec4.xy, 1.0, 1.0);
}`;

// The Fragment Shader for the background. This is where the colorful pattern is generated.
const fragShader2D = `#ifdef GL_ES
precision highp float;
#endif
uniform vec2 iResolution; // The resolution of the canvas.
uniform float iTime;       // A timer value for animation.
varying vec2 vTexCoord;   // The coordinate of the current pixel.

// A color palette function by Iñigo Quilez. It generates smooth, nice colors based on a single input value 't'.
vec3 palette( float t ){ vec3 a = vec3(0.5, 0.5, 0.5); vec3 b = vec3(0.5, 0.5, 0.5); vec3 c = vec3(1.0, 1.0, 1.0); vec3 d = vec3(0.263,0.416,0.557); return a + b*cos( 6.28318*(c*t+d) ); }

void main() {
  // Normalize the coordinates and correct for aspect ratio.
  vec2 uv = vTexCoord * 2.0 - 1.0;
  uv.x *= 1.0 * iResolution.x / iResolution.y;
  vec2 uv0 = uv; // Keep the original coordinate.
  vec3 finalColor = vec3(0.0);

  // A loop to create a fractal-like pattern by layering calculations.
  for (float i = 0.0; i < 4.0; i++) {
    uv = fract(uv * 1.5) - 0.5; // Fold the coordinate space.
    float d = length(uv) * exp(-length(uv0));
    vec3 col = palette(length(uv0) + i*0.4 + iTime*0.4); // Get a color from the palette.
    d = sin(d*8.0 + iTime) / 8.0; // Create a wave effect.
    d = abs(d);
    d = pow(0.01 / d, 1.2); // Enhance the brightness.
    finalColor += col * d; // Add the resulting color to the final output.
  }
  gl_FragColor = vec4(finalColor, 1.0);
}`;

// 2. Shaders for the 3D Objects (the Cubes)

// The Vertex Shader for the 3D cubes. It positions the cubes in 3D space.
const vertShader3D = `
#ifdef GL_ES
precision highp float;
#endif
// Attributes received from p5.js for each vertex.
attribute vec3 aPosition; // The vertex's position.
attribute vec3 aNormal;   // The vertex's normal (which way the face is pointing).

// Uniforms are global variables passed from p5.js.
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

// Varyings are variables passed from the vertex shader to the fragment shader.
varying vec3 vPosition;
varying vec3 vNormal;

void main() {
  // Pass the position and normal to the fragment shader.
  vPosition = aPosition;
  vNormal = aNormal;

  // Calculate the final position of the vertex on the screen.
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
}`;

// The Fragment Shader for the 3D cubes. It calculates the pattern and lighting for the cubes' surfaces.
const fragShader3D = `#ifdef GL_ES
precision highp float;
#endif
// Uniforms from p5.js
uniform float iTime;
uniform float uBoxSize;

// Varyings from the vertex shader
varying vec3 vPosition;
varying vec3 vNormal;

// The same color palette function as the background.
vec3 palette( float t ){ vec3 a = vec3(0.5, 0.5, 0.5); vec3 b = vec3(0.5, 0.5, 0.5); vec3 c = vec3(1.0, 1.0, 1.0); vec3 d = vec3(0.263,0.416,0.557); return a + b*cos( 6.28318*(c*t+d) ); }

void main() {
  // STEP 1: Calculate the procedural pattern color, just like the background.
  // The pattern is based on the 3D position of the pixel on the cube's surface.
  vec3 p = vPosition / (uBoxSize / 2.0); // Normalize position based on box size.
  vec3 p0 = p;
  vec3 patternColor = vec3(0.0);
  for (float i = 0.0; i < 4.0; i++) {
    p = fract(p * 1.5) - 0.5;
    float d = length(p) * exp(-length(p0));
    vec3 col = palette(length(p0) + i*0.4 + iTime*0.4);
    d = sin(d*8.0 + iTime) / 8.0;
    d = abs(d);
    d = pow(0.01 / d, 1.2);
    patternColor += col * d;
  }

  // STEP 2: Calculate lighting to give the cube depth.
  vec3 lightDir = normalize(vec3(0.5, 1.0, 0.8)); // A fixed light direction from the top-right.
  vec3 normal = normalize(vNormal); // The direction the cube face is pointing.
  // The dot product tells us how much the surface is facing the light.
  float diffuse = max(0.0, dot(normal, lightDir));

  // STEP 3: Combine the pattern color with the lighting.
  float ambient = 0.2; // A small amount of ambient light to illuminate shadows.
  vec3 finalColor = patternColor * (diffuse * 0.8 + ambient);

  gl_FragColor = vec4(finalColor, 1.0);
}`;


// ===============================================================
// P5.JS MAIN CODE
// ===============================================================
let backgroundShader;
let objectShader;

function setup() {
  // Create a canvas that fills the window, using WEBGL mode.
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(1); // Set pixel density to 1 for consistent performance.
  noStroke(); // We don't need outlines for our shapes.

  // Compile and link the shaders into two separate shader programs.
  backgroundShader = createShader(vertShader2D, fragShader2D);
  objectShader = createShader(vertShader3D, fragShader3D);
}

function draw() {
  const iTime = millis() / 1000.0; // Get the elapsed time in seconds for animation.

  // --- Draw the Background ---
  shader(backgroundShader); // Activate the background shader.
  backgroundShader.setUniform("iResolution", [width, height]);
  backgroundShader.setUniform("iTime", iTime);
  rect(-width/2, -height/2, width, height); // Draw a rectangle covering the canvas.

  // --- Draw the 5 Cubes ---
  resetShader(); // Reset to default p5.js state before drawing 3D objects.
  shader(objectShader); // Activate the 3D object shader.
  objectShader.setUniform("iTime", iTime);

  // Calculate the size and distance of the cubes based on the shorter side of the window.
  // This makes the sketch responsive.
  let shorterSide = max(width, height);
  let boxSize = shorterSide * 0.2;
  let distance = boxSize * 1.5;
  objectShader.setUniform("uBoxSize", boxSize);

  // 1. Central Cube
  push(); // Save the current drawing state (position, rotation).
  rotateX(iTime * 0.5);
  rotateY(iTime * 0.4);
  box(boxSize);
  pop(); // Restore the drawing state (so the next cube starts at the center).

  // 2. Right Cube
  push();
  translate(distance, 0, 0); // Move to the right.
  rotateX(iTime * 0.3);      // Use a different rotation speed.
  rotateY(iTime * 0.6);
  box(boxSize);
  pop();

  // 3. Left Cube
  push();
  translate(-distance, 0, 0); // Move to the left.
  rotateX(iTime * 0.3);
  rotateY(iTime * 0.6);
  box(boxSize);
  pop();

  // 4. Top Cube
  push();
  translate(0, -distance, 0); // Move up (in WEBGL, negative Y is up).
  rotateX(iTime * 0.6);
  rotateY(iTime * 0.3);
  box(boxSize);
  pop();

  // 5. Bottom Cube
  push();
  translate(0, distance, 0); // Move down.
  rotateX(iTime * 0.6);
  rotateY(iTime * 0.3);
  box(boxSize);
  pop();
}

// This function is called automatically whenever the browser window is resized.
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
